'use strict';
const $ = id => document.getElementById(id);
const state = {snapshot:null, legacySnapshot:null, runs:[], selected:null};
const studyRunCache=new Map();
const NS = 'http://www.w3.org/2000/svg';
const pct = value => value == null ? 'N/A' : `${(100 * value).toFixed(1)}%`;
const secs = value => value == null ? 'N/A' : value < 60 ? `${value.toFixed(1)}s` : `${(value/60).toFixed(1)}m`;
const mean = xs => { const values=xs.filter(x=>x!=null);return values.length?values.reduce((a,b)=>a+b,0)/values.length:null; };
const median = xs => {const sorted=xs.filter(x=>x!=null).sort((a,b)=>a-b);return sorted.length?(sorted[Math.floor((sorted.length-1)/2)]+sorted[Math.floor(sorted.length/2)])/2:null;};
function el(tag,text,cls){const node=document.createElement(tag);if(text!=null)node.textContent=String(text);if(cls)node.className=cls;return node;}
function svg(tag,attrs={},text){const node=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>node.setAttribute(k,String(v)));if(text!=null)node.textContent=String(text);return node;}
function empty(target,text){target.replaceChildren(el('p',text,'empty'));}
function options(target,values,allLabel){const previous=target.value;target.replaceChildren(new Option(allLabel,'all'),...values.map(v=>new Option(v,v)));target.value=values.includes(previous)?previous:'all';}
function cohortLabel(run){return run.study_row?`${run.backend} · v${run.protocol_version} · ${run.study_row.task_family}/${run.study_row.split} · ${run.rounds} rounds · ${run.study_row.worker_label} · freeze ${run.study_row.freeze_hash.slice(0,12)}`:`${run.backend} · v${run.protocol_version} · ${run.thinking} thinking · ${run.cohort}`;}
function filtered(){return state.snapshot.runs.filter(r=>($('backend').value==='all'||($('backend').value==='mock'?r.backend==='mock':r.backend!=='mock'))&&($('model').value==='all'||r.model===$('model').value)&&($('topology').value==='all'||r.topology===$('topology').value)&&($('condition').value==='all'||r.intervention===$('condition').value));}
function render(){
 const models=state.snapshot.runs.filter(r=>$('backend').value==='all'||($('backend').value==='mock'?r.backend==='mock':r.backend!=='mock')).map(r=>r.model);
 options($('model'),[...new Set(models)].sort(),'All models');
 state.runs=filtered();const complete=state.runs.filter(r=>r.status==='completed');
 $('runs-kpi').textContent=`${complete.length} / ${state.runs.length}`;
 const cohorts=new Set(complete.map(r=>r.cohort));
 $('runs-sub').textContent=`${state.runs.length-complete.length} failed/exhausted · ${cohorts.size} cohort(s)`;
 // Avoid a misleading aggregate across different models, protocols, and sampling settings.
 $('adoption-kpi').textContent=cohorts.size>1?'By cohort':pct(mean(complete.map(r=>r.downstream_adoption_rate)));
 $('boundary-kpi').textContent=cohorts.size>1?'By cohort':pct(mean(complete.map(r=>r.downstream_clean_rate)));
 $('runtime-kpi').textContent=secs(median(state.runs.map(r=>r.duration_seconds)));
 const note=$('dataset-note');const hasMock=state.runs.some(r=>r.backend==='mock');note.classList.toggle('mock',hasMock);
 note.textContent=!state.runs.length?'No runs match these filters. Select mock validation to inspect the software demonstration.':hasMock?'MOCK DATA PRESENT — scripted software validation. It provides no empirical evidence about LLM alignment. Cohorts remain separate below.':'LIVE INFERENCE — all indexed protocols and task families. Cohorts stay separate; N/A means unrecorded or inapplicable. Includes development, timing and integration attempts.';
 renderTable();renderPlots();renderTaskCoverage();
 const previous=$('run-select').value;$('run-select').replaceChildren(...state.runs.map(r=>new Option(`${r.model} · ${r.topology} · ${r.intervention==='none'?'control':'injected'} · seed ${r.seed} · ${r.status} · ${r.id.slice(0,6)}`,r.id)));
 if(state.runs.some(r=>r.id===previous))$('run-select').value=previous;
 selectRun();renderObservability();
}
function groups(runs,key){const result=new Map();runs.forEach(r=>{const k=key(r);if(!result.has(k))result.set(k,[]);result.get(k).push(r);});return [...result.values()];}
const comparisonOpen=new Set();
function renderTable(){
 const target=$('comparison');target.replaceChildren();const query=$('comparison-search').value.trim().toLowerCase();
 const rows=state.runs.filter(r=>`${r.model} ${cohortLabel(r)} ${r.topology} ${r.intervention} ${r.intervention==='none'?'control':'injected'}`.toLowerCase().includes(query));
 const modelGroups=groups(rows,r=>[r.model,r.backend].join('|')).sort((a,b)=>a[0].model.localeCompare(b[0].model));
 $('comparison-count').textContent=`${modelGroups.length} model / backend groups · ${rows.length} attempts shown · expand for exact cohort results`;
 if(!rows.length){empty(target,'No comparison results match these filters.');return;}
 for(const runs of modelGroups){
  const first=runs[0],key=JSON.stringify([first.model,first.backend]),conditions=groups(runs,r=>[r.cohort,r.topology,r.intervention].join('|'));
  const card=el('article',null,'comparison-card'),head=el('div',null,'comparison-card-heading'),title=el('h3',first.model);
  head.append(title,el('span',first.backend.toUpperCase(),`badge ${first.backend==='mock'?'mock':''}`));card.append(head);
  const protocols=[...new Set(runs.map(r=>r.protocol_version))].sort();card.append(el('p',`Protocols ${protocols.join(' / ')} · ${new Set(runs.map(r=>r.cohort)).size} separate cohorts`,'caption'));
  const stats=el('div',null,'comparison-stats');
  [[`${runs.filter(r=>r.status==='completed').length} / ${runs.length}`,'complete / attempts'],[conditions.length,'network / treatment groups'],[secs(median(runs.map(r=>r.duration_seconds))),'median attempt time']].forEach(([value,label])=>{const item=el('div');item.append(el('strong',value),el('small',label));stats.append(item);});card.append(stats);
  const metrics=el('div',null,'comparison-metrics');
  for(const [field,label,color] of [['legitimate_task_success_rate','Task success','#40bf91'],['downstream_adoption_rate','Suffix adoption','#ef7988'],['downstream_clean_rate','Clean boundary adherence','#409cff']]){
   const values=conditions.map(g=>mean(g.filter(r=>r.status==='completed').map(r=>r[field]))).filter(v=>v!=null),row=el('div',null,'comparison-metric'),labels=el('div',null,'comparison-metric-label');
   const lo=values.length?Math.min(...values):null,hi=values.length?Math.max(...values):null;
   labels.append(el('span',label),el('b',lo==null?'N/A':lo===hi?pct(lo):`${pct(lo)} – ${pct(hi)}`));row.append(labels);
   const track=el('div',null,'comparison-range');track.setAttribute('role','img');track.setAttribute('aria-label',`${label}: ${lo==null?'not available':pct(lo)+' to '+pct(hi)} across ${values.length} measured condition groups`);
   if(lo!=null){const range=el('span');range.style.left=`${lo*100}%`;range.style.width=`${(hi-lo)*100}%`;range.style.background=color;track.append(range);}else track.classList.toggle('unmeasured',true);
   row.append(track);metrics.append(row);
  }card.append(metrics,el('p','Range across measured condition means; not a pooled score.','caption'));
  const detail=el('details',null,'comparison-detail'),summary=el('summary',`Explore ${conditions.length} cohort / network / treatment results`),content=el('div',null,'table-scroll');detail.append(summary,content);
  function fill(){
   const table=el('table'),thead=el('thead'),header=el('tr');['Cohort / protocol','Network / condition','Complete / attempts','Adoption','Boundary','Task success','Run time','Call latency','Messages / run'].forEach(t=>header.append(el('th',t)));thead.append(header);const body=el('tbody');
   for(const group of conditions){const run=group[0],done=group.filter(r=>r.status==='completed'),row=el('tr');
    [cohortLabel(run),run.topology+' / '+(run.intervention==='none'?'control':'injected'),`${done.length} / ${group.length}`,pct(mean(done.map(r=>r.downstream_adoption_rate))),pct(mean(done.map(r=>r.downstream_clean_rate))),pct(mean(done.map(r=>r.legitimate_task_success_rate))),secs(median(group.map(r=>r.duration_seconds))),secs(median(group.map(r=>r.median_call_seconds))),mean(done.map(r=>r.messages_delivered))?.toFixed(0)??'N/A'].forEach(value=>row.append(el('td',value)));body.append(row);
   }table.append(thead,body);content.replaceChildren(table);
  }
  detail.open=comparisonOpen.has(key);if(detail.open)fill();detail.addEventListener('toggle',()=>{if(detail.open){comparisonOpen.add(key);fill();}else comparisonOpen.delete(key);});card.append(detail);target.append(card);
 }
}
$('comparison-search').addEventListener('input',renderTable);

function taskFamily(run){return run.study_row?.task_family??'legacy_summary';}
function renderTaskCoverage(){
 const rows=state.runs,families=[...new Set(rows.map(taskFamily))].sort(),models=groups(rows,r=>[r.model,r.backend].join('|')).sort((a,b)=>a[0].model.localeCompare(b[0].model));
 options($('coverage-task'),families,'All task families');const metric=$('coverage-metric').value||'completed';
 $('coverage-summary').textContent=`${new Set(rows.map(r=>r.model)).size} model tags · ${families.length} task families · ${rows.filter(r=>r.status==='completed').length}/${rows.length} completed attempts. Legacy task semantics and newer protocols remain distinct.`;
 const table=el('table'),head=el('tr');head.append(el('th','Model / backend'));families.forEach(f=>head.append(el('th',f.replaceAll('_',' '))));const header=el('thead');header.append(head);table.append(header);const body=el('tbody');
 const value=g=>metric==='calls'?g.reduce((n,r)=>n+r.completed_calls,0):metric==='attempts'?g.length:g.filter(r=>r.status==='completed').length;
 const maximum=Math.max(1,...models.flatMap(g=>families.map(f=>value(g.filter(r=>taskFamily(r)===f)))));
 for(const group of models){const row=el('tr');row.append(el('th',`${group[0].model} / ${group[0].backend}`));for(const family of families){const selected=group.filter(r=>taskFamily(r)===family),cell=el('td'),button=el('button',selected.length?compact(value(selected)):'—','coverage-cell');button.type='button';button.disabled=!selected.length;button.style.background=`rgba(64,156,255,${selected.length?.08+.65*value(selected)/maximum:0})`;button.setAttribute('aria-label',`${group[0].model}, ${family}: ${value(selected)} ${metric}`);button.addEventListener('click',()=>{$('coverage-task').value=family;renderTaskCoverage();});cell.append(button);row.append(cell);}body.append(row);}table.append(body);$('coverage-heatmap').replaceChildren(table);
 if(!rows.length){['coverage-bars','coverage-scatter'].forEach(id=>empty($(id),'No attempts match the current filters.'));return;}
 const bar=svg('svg',{viewBox:`0 0 620 ${Math.max(200,families.length*42+25)}`,role:'img','aria-label':'Completed versus interrupted attempt counts by task'}),max=Math.max(1,...families.map(f=>rows.filter(r=>taskFamily(r)===f).length));
 families.forEach((family,i)=>{const group=rows.filter(r=>taskFamily(r)===family),done=group.filter(r=>r.status==='completed').length,y=20+i*42;bar.append(svg('text',{x:0,y,class:'axis-label'},family.replaceAll('_',' ')),svg('rect',{x:145,y:y-10,width:done/max*340,height:15,fill:'#40bf91',rx:2}),svg('rect',{x:145+done/max*340,y:y-10,width:(group.length-done)/max*340,height:15,fill:'#e59d42',rx:2}),svg('text',{x:495,y:y+2,class:'axis-label'},`${done} complete / ${group.length-done} other`));});$('coverage-bars').replaceChildren(bar);
 const selected=rows.filter(r=>($('coverage-task').value==='all'||taskFamily(r)===$('coverage-task').value)&&Number.isFinite(r.duration_seconds)&&Number.isFinite(r.completed_calls));
 if(!selected.length){empty($('coverage-scatter'),'No recorded timing for this selection.');return;}
 const plot=svg('svg',{viewBox:'0 0 620 300',role:'img','aria-label':'Attempt runtime versus returned model calls; click a point to inspect its trace'}),xmax=Math.max(1,...selected.map(r=>r.completed_calls)),ymax=Math.max(1,...selected.map(r=>r.duration_seconds));
 for(let i=0;i<=4;i++){const x=62+i*130,y=250-i*52;plot.append(svg('line',{x1:62,y1:y,x2:585,y2:y,class:'gridline'}),svg('text',{x:4,y:y+4,class:'axis-label'},secs(ymax*i/4)),svg('text',{x,y:270,'text-anchor':'middle',class:'axis-label'},Math.round(xmax*i/4)));}plot.append(svg('text',{x:320,y:294,'text-anchor':'middle',class:'axis-label'},'Returned responses'));
 const palette=['#409cff','#40bf91','#e59d42','#a58bff','#ef7988','#40c5d0'];
 for(const run of selected){const index=models.findIndex(g=>g[0].model===run.model&&g[0].backend===run.backend),dot=svg('circle',{cx:62+run.completed_calls/xmax*520,cy:250-run.duration_seconds/ymax*208,r:4.5,fill:palette[index%palette.length],opacity:run.status==='completed'?.75:.4,role:'button',tabindex:0});const label=`${run.model} / v${run.protocol_version} / ${taskFamily(run)} / ${run.rounds} rounds / ${run.status}: ${run.completed_calls} responses, ${secs(run.duration_seconds)}`;dot.append(svg('title',{},label));dot.setAttribute('aria-label',label);const inspect=()=>{$('run-select').value=run.id;selectRun();showView('traces');};dot.addEventListener('click',inspect);dot.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();inspect();}});plot.append(dot);}
 const legend=el('div',null,'coverage-legend');models.forEach((g,i)=>{const item=el('span',`${g[0].model} / ${g[0].backend}`);item.style.color=palette[i%palette.length];legend.append(item);});$('coverage-scatter').replaceChildren(plot,legend);
}
['coverage-metric','coverage-task'].forEach(id=>$(id).addEventListener('change',renderTaskCoverage));

function renderPlots(){
 const target=$('adoption-chart');target.replaceChildren();const grouped=groups(state.runs.filter(r=>r.status==='completed'&&r.downstream_adoption_rate!=null),r=>[r.cohort,r.topology,r.intervention].join('|'));
 if(!grouped.length)empty(target,'No completed runs in this selection.');else{
 const width=Math.max(500,grouped.length*115),height=270,plot=svg('svg',{viewBox:`0 0 ${width} ${height}`,role:'img','aria-label':'Run-level downstream adoption by cohort, network and condition'});
 [0,.25,.5,.75,1].forEach(v=>{const y=190-v*160;plot.append(svg('line',{x1:42,y1:y,x2:width-15,y2:y,class:'gridline'}),svg('text',{x:4,y:y+4,class:'axis-label'},`${v*100}%`));});
 grouped.forEach((g,i)=>{const x=65+(i+.5)*(width-90)/grouped.length;g.forEach((r,j)=>{const dot=svg('circle',{cx:x+(j-(g.length-1)/2)*7,cy:190-r.downstream_adoption_rate*160,r:4,class:`chart-dot ${r.intervention!=='none'?'injected':''}`});dot.append(svg('title',{},`${r.model} / ${r.cohort} / seed ${r.seed}: ${pct(r.downstream_adoption_rate)}`));plot.append(dot);});[g[0].model,g[0].topology+' / '+(g[0].intervention==='none'?'control':'injected'),g[0].cohort.slice(0,6)].forEach((text,j)=>plot.append(svg('text',{x,y:211+j*15,'text-anchor':'middle',class:'axis-label'},text)));});target.append(plot);}
 const runtime=$('runtime-chart');runtime.replaceChildren();const runtimeGroups=groups(state.runs,r=>r.cohort);if(!runtimeGroups.length){empty(runtime,'No attempts in this selection.');return;}
 const width=600,height=Math.max(260,runtimeGroups.length*65+25),plot=svg('svg',{viewBox:`0 0 ${width} ${height}`,role:'img','aria-label':'Median wall-clock run time by model cohort'});const max=Math.max(...state.runs.map(r=>r.duration_seconds),.001);
 runtimeGroups.forEach((g,i)=>{const y=25+i*65;plot.append(svg('text',{x:0,y,class:'axis-label'},`${g[0].model} / ${g[0].cohort.slice(0,6)}`));const value=median(g.map(r=>r.duration_seconds));plot.append(svg('rect',{x:0,y:y+9,width:Math.max(1,value/max*510),height:15,fill:g[0].backend==='mock'?'#d5a04a':'#409cff',rx:2}),svg('text',{x:Math.min(515,value/max*510+6),y:y+21,class:'axis-label'},secs(value)));});runtime.append(plot);
}
function selectRun(){state.selected=state.runs.find(r=>r.id===$('run-select').value)||null;const run=state.selected;$('run-meta').replaceChildren();if(!run){['network','agents','trajectory','run-details','trace-list'].forEach(id=>empty($(id),'Select a run to inspect its evidence.'));renderRunQuality();return;}
 [run.status,run.backend.toUpperCase(),`protocol ${run.protocol_version}`,`seed ${run.seed}`,`thinking ${run.thinking}`,`cohort ${run.cohort}`].forEach(text=>$('run-meta').append(el('span',text,'meta-chip')));
 $('round').max=String(run.rounds-1);$('round').value=String(Math.min(Number($('round').value),run.rounds-1));
 $('run-details').replaceChildren();const details={Model:run.model,Digest:run.model_digest??'Not supplied',Runtime:secs(run.duration_seconds),'Calls returned / invoked':`${run.completed_calls} / ${run.attempted_calls}`,'HTTP attempts':run.http_attempts??'Not recorded','Parse failures':run.parse_failures,'Generated tokens':run.generated_tokens??'Not recorded','Generation tokens/s':run.generation_tokens_per_second?.toFixed(1)??'Not recorded','First adoption delay':run.first_downstream_adoption==null?(run.study_row?'Not recorded':'None observed'):`${run.first_downstream_adoption} round(s)`,'Maximum distance':run.maximum_propagation_distance??'N/A','Config sampling':`temperature ${run.temperature} / ${run.max_output_tokens} tokens`,'Started UTC':run.started_utc,'Source hash':run.source_hash};Object.entries(details).forEach(([key,value])=>$('run-details').append(el('dt',key),el('dd',value)));
 renderRound();renderRunQuality();if(run.study_row)loadStudyRun(run);
}
function agentState(agent){if(!agent)return'waiting';if(agent.adopted_instruction||agent.objective_violation)return'adopted';if(agent.legitimate_task_success)return'clean';if(agent.exposed)return'exposed';return'waiting';}
function renderRound(){const run=state.selected;if(!run)return;const round=Number($('round').value);$('round-label').textContent=String(round);const observed=[...run.timeline].reverse().find(t=>t.round<=round);const agentMap=new Map((observed?.agents??[]).map(a=>[a.agent_id,a]));
 const graph=svg('svg',{viewBox:'0 0 480 300',role:'img','aria-label':`${run.topology} network at round ${round}`});const coords={};Object.keys(run.graph).forEach((id,i)=>{const angle=-Math.PI/2+i*2*Math.PI/Math.max(1,Object.keys(run.graph).length);coords[id]=run.topology==='star'?(i===0?[240,145]:[240+120*Math.cos((i-1)*2*Math.PI/Math.max(1,Object.keys(run.graph).length-1)),145+100*Math.sin((i-1)*2*Math.PI/Math.max(1,Object.keys(run.graph).length-1))]):[240+145*Math.cos(angle),145+112*Math.sin(angle)];});
 Object.entries(run.graph).forEach(([sender,neighbors])=>neighbors.forEach(receiver=>{if(sender<receiver){const [x1,y1]=coords[sender],[x2,y2]=coords[receiver];graph.append(svg('line',{x1,y1,x2,y2,class:'edge'}));}}));
 Object.entries(coords).forEach(([id,[x,y]])=>{const group=svg('g',{});group.append(svg('circle',{cx:x,cy:y,r:28,class:`node ${agentState(agentMap.get(id))}`}),svg('text',{x,y:y+4,'text-anchor':'middle',class:'node-label'},id.replace('agent_','A')));if(id===run.initial_agent_id)group.append(svg('text',{x,y:y+43,'text-anchor':'middle',class:'node-role'},run.intervention==='none'?'designated source':'injection source'));graph.append(group);});$('network').replaceChildren(graph);
 $('agents').replaceChildren();Object.keys(run.graph).forEach(id=>{const a=agentMap.get(id),row=el('div',null,'agent-row'),left=el('div',id);left.append(el('small',` · ${a?.messages_received??'unknown'} received${a?.exposed?' · exposed':''}${a?.quoted_only?' · quoted only':''}${a?.stated_agreement?' · agreement heuristic':''}`));const kind=agentState(a);row.append(left,el('span',!a||a.reason_code==='missing_or_ambiguous_artifact'?'Unknown / ambiguous':a.adopted_instruction?'Adopted suffix':a.objective_violation?'Objective violation':a.legitimate_task_success?'Valid clean answer':a.quoted_only?'Quotation':'Other answer',`agent-state ${kind}`));$('agents').append(row);});
 $('trajectory').replaceChildren();run.timeline.forEach(t=>{const button=el('button',`Round ${t.round}`,`round-step ${t.round===round?'active':''}`);button.type='button';button.append(el('b',pct(t.adoption_rate)));button.addEventListener('click',()=>{$('round').value=String(t.round);renderRound();});$('trajectory').append(button);});renderTraces();
}
function renderTraces(){const run=state.selected,target=$('trace-list');target.replaceChildren();$('trace-count').textContent='0 events';if(!run)return;if(!(run.study_row?run.traces_included:state.snapshot.traces_included)){empty(target,'Free-text traces were withheld from this public snapshot. Agent outcomes and routing remain available.');return;}
 const agent=$('trace-agent').value,type=$('trace-type').value,query=$('trace-search').value.toLowerCase();const traces=run.traces.filter(e=>e.round<=Number($('round').value)&&(agent==='all'||[e.agent_id,e.sender_id,e.receiver_id].includes(agent))&&(type==='all'||e.event_type===type)&&`${e.content??''} ${e.thinking??''}`.toLowerCase().includes(query));
 $('trace-count').textContent=`${traces.length} events`;
 for(const e of traces){const item=el('details',null,`trace-item event-${e.event_type}`);const label=[e.event_id,`r${e.round}`,e.event_type,e.agent_id??e.sender_id??'',e.receiver_id?`→ ${e.receiver_id}`:'',e.duration_seconds!=null?secs(e.duration_seconds):''].filter(Boolean).join(' · ');item.append(el('summary',label));if(e.content!=null){let content=e.content;try{content=JSON.stringify(JSON.parse(content),null,2);}catch{}item.append(el('pre',content));}if(e.thinking)item.append(el('pre',`GENERATED REASONING TEXT\n${e.thinking}`,'trace-thinking'));if(e.event_type==='artifact')item.open=true;target.append(item);}if(!traces.length)empty(target,'No events match the selected round and filters.');
}
async function load(){try{const response=await fetch(`data/results.json?v=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error('Snapshot could not be loaded');const data=await response.json();if(data.schema_version!=='1.0'||!Array.isArray(data.runs))throw new Error('Unsupported snapshot schema');$('error').hidden=true;if(state.snapshot?.generated_utc===data.generated_utc)return;state.legacySnapshot=data;state.snapshot=data;combineEvidence();$('updated').textContent=`Legacy results exported ${new Date(data.generated_utc).toLocaleString()}`;$('privacy-state').textContent=data.traces_included?'Scrubbed trace export · manual review required':'Summary only · free-text traces withheld';$('redaction-note').textContent=`Snapshot redactions: ${data.redaction_replacements}. Unsealed runs omitted: ${data.skipped_unsealed}. Heuristic scrubbing cannot guarantee anonymity; raw data is never served.`;if(!data.runs.some(r=>r.backend!=='mock')&&$('backend').value==='live')$('backend').value='mock';render();renderEvidenceCensus();renderEvidenceInventory();}catch(error){$('error').hidden=false;$('error').textContent='The snapshot could not be loaded. Serve this directory over HTTP and verify data/results.json exists. No live model connection is made by this page.';}}
['backend','model','topology','condition'].forEach(id=>$(id).addEventListener('change',render));$('run-select').addEventListener('change',selectRun);$('round').addEventListener('input',renderRound);['trace-agent','trace-type','trace-search'].forEach(id=>$(id).addEventListener('input',renderTraces));$('refresh').addEventListener('click',()=>Promise.all([load(),loadResearch(),loadRepositories()]));load();

// Poll only public same-origin data; preserve open traces when the export is unchanged.
setInterval(()=>{if(!document.hidden)load();},60000);

const VIEW_LABELS={
 research:['Scenarios, Benchmarks & Review','Frozen scenario samples, task metrics, and uncalibrated independent review'],
 neural:['Interpretability Explorer','Measured activations, controlled patches, and behavioral monitor evidence'],
 overview:['Swarm Observability & Evaluation','Model behavior, network propagation, and trace-level evidence'],
 models:['Model & Protocol Comparison','Compare matched model cohorts, conditions, latency, and resource use'],
 evaluations:['Evaluation Results','Validated behavior, output quality, exposure, and run-level outcomes'],
 traces:['Trace Explorer','Inspect sanitized responses, inter-agent messages, and round-by-round routing'],
 datasets:['Published Datasets','Inspect cohort coverage and download the sanitized research snapshot'],
 methods:['Methods & Evaluation Tools','Measurement definitions, privacy boundaries, and interpretation limits']
};
function showView(name,updateHash=true){
 if(!VIEW_LABELS[name])name='overview';
 document.body.dataset.view=name;
 $('view-title').textContent=VIEW_LABELS[name][0];$('view-subtitle').textContent=VIEW_LABELS[name][1];
 Object.keys(VIEW_LABELS).forEach(view=>{const link=$(`nav-${view}`);link.classList.toggle('active',view===name);link.setAttribute('aria-current',view===name?'page':'false');});
 document.body.classList.remove('sidebar-open');
 if(typeof window!=='undefined'&&updateHash)window.history.pushState(null,'',`#${name}`);
}
Object.keys(VIEW_LABELS).forEach(view=>$(`nav-${view}`).addEventListener('click',event=>{event.preventDefault();showView(view);}));
$('view-models').addEventListener('click',event=>{event.preventDefault();showView('models');});
$('inspect-run').addEventListener('click',event=>{event.preventDefault();showView('traces');});
$('nav-toggle').addEventListener('click',()=>document.body.classList.toggle('sidebar-open'));
$('nav-overlay').addEventListener('click',()=>document.body.classList.remove('sidebar-open'));
showView(typeof window!=='undefined'?window.location.hash.slice(1):'overview',false);
if(typeof window!=='undefined'){window.addEventListener('hashchange',()=>showView(window.location.hash.slice(1),false));window.addEventListener('popstate',()=>showView(window.location.hash.slice(1),false));}

function compact(value){return value==null?'N/A':Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(value);}
function cohortRange(runs,field){const values=groups(runs,r=>r.cohort).map(rs=>mean(rs.map(r=>r[field]))).filter(v=>v!=null);if(!values.length)return'N/A';const min=Math.min(...values),max=Math.max(...values);return Math.abs(max-min)<1e-9?pct(min):`${Math.round(100*min)}–${Math.round(100*max)}%`;}
function sparkline(id,values,bounded=false){
 const target=$(id);target.replaceChildren();const data=values.filter(v=>v!=null&&Number.isFinite(v));if(!data.length){target.append(el('span','Not recorded','panel-tag'));return;}
 const max=bounded?1:Math.max(...data,1),width=140,height=28;
 const points=data.map((v,i)=>[data.length===1?width/2:i*width/(data.length-1),height-3-v/max*(height-6)]);
 const chart=svg('svg',{viewBox:`0 0 ${width} ${height}`,role:'img','aria-label':'Recorded values in chronological run order'});
 const path=points.map(([x,y],i)=>`${i?'L':'M'} ${x} ${y}`).join(' ');
 chart.append(svg('path',{d:`${path} L ${points.at(-1)[0]} ${height} L ${points[0][0]} ${height} Z`,class:'spark-area'}),svg('path',{d:path,class:'spark-line'}));target.append(chart);
}
function renderObservability(){
 const runs=[...state.runs].sort((a,b)=>String(a.started_utc??a.id).localeCompare(String(b.started_utc??b.id))),done=runs.filter(r=>r.status==='completed');
 $('adoption-kpi').textContent=cohortRange(done,'downstream_adoption_rate');
 $('boundary-kpi').textContent=cohortRange(done,'downstream_clean_rate');
 $('task-kpi').textContent=cohortRange(done,'legitimate_task_success_rate');
 const latency=median(runs.map(r=>r.median_call_seconds));$('latency-kpi').textContent=latency!=null&&latency<1?`${Math.round(latency*1000)}ms`:secs(latency);
 const knownTokens=runs.filter(r=>r.generated_tokens!=null),tokens=knownTokens.length?knownTokens.reduce((n,r)=>n+r.generated_tokens,0):null;$('tokens-kpi').textContent=compact(tokens);$('tokens-coverage').textContent=`Recorded in ${knownTokens.length}/${runs.length} selected attempts`; $('latency-coverage').textContent=`Recorded medians: ${runs.filter(r=>r.median_call_seconds!=null).length}/${runs.length} attempts`;
 $('errors-kpi').textContent=runs.length?pct(runs.filter(r=>r.status!=='completed').length/runs.length):'N/A';
 $('runs-sub').textContent=`${compact(runs.reduce((n,r)=>n+r.completed_calls,0))} responses · ${new Set(runs.map(r=>r.cohort)).size} cohorts`;
 $('trace-nav-count').textContent=compact(runs.reduce((n,r)=>n+r.completed_calls,0));$('trace-nav-count').setAttribute('title','Returned model responses in the current selection');
 const dates=runs.filter(r=>r.started_utc).map(r=>r.started_utc.slice(0,10)).sort();$('date-range').textContent=dates.length?dates[0]===dates.at(-1)?`${dates[0]} · UTC`:`${dates[0]} → ${dates.at(-1)} · UTC`:'No matching runs';
 sparkline('latency-spark',runs.map(r=>r.median_call_seconds));sparkline('runs-spark',runs.map((_,i)=>i+1));sparkline('tokens-spark',runs.map(r=>r.generated_tokens));sparkline('task-spark',runs.map(r=>r.legitimate_task_success_rate),true);sparkline('adoption-spark',runs.map(r=>r.downstream_adoption_rate),true);sparkline('boundary-spark',runs.map(r=>r.downstream_clean_rate),true);sparkline('errors-spark',runs.map(r=>r.status==='completed'?0:1),true);sparkline('runtime-spark',runs.map(r=>r.duration_seconds));
 renderActivity(runs);renderObservations(runs);renderDistribution(done);renderDatasets(runs);renderRunQuality();
}
function renderActivity(runs){
 const target=$('activity-chart');if(!runs.length){empty(target,'No run history matches these filters.');return;}
 const totals=[];let returned=0,missing=0;runs.forEach(r=>{returned+=r.completed_calls;missing+=Math.max(0,r.attempted_calls-r.completed_calls);totals.push({returned,missing});});
 const width=540,height=245,left=40,right=18,top=12,bottom=38,max=Math.max(returned,missing,1),plot=svg('svg',{viewBox:`0 0 ${width} ${height}`,role:'img','aria-label':'Cumulative returned responses and unreturned logical invocations, by chronological run'});
 for(let i=0;i<=4;i++){const y=top+(height-top-bottom)*(1-i/4);plot.append(svg('line',{x1:left,y1:y,x2:width-right,y2:y,class:'gridline'}),svg('text',{x:2,y:y+3,class:'axis-label'},compact(max*i/4)));}
 const x=i=>left+(runs.length===1?.5:i/(runs.length-1))*(width-left-right),y=v=>height-bottom-v/max*(height-top-bottom);
 for(const [field,color] of [['returned','#409cff'],['missing','#f06473']]){
 const points=totals.map((v,i)=>`${x(i)},${y(v[field])}`).join(' ');plot.append(svg('polyline',{points,fill:'none',stroke:color,'stroke-width':2}));
 totals.forEach((v,i)=>{const dot=svg('circle',{cx:x(i),cy:y(v[field]),r:3,fill:color});dot.append(svg('title',{},`${runs[i].model} · seed ${runs[i].seed} · ${field}: ${v[field]}`));plot.append(dot);});}
 const step=Math.max(1,Math.ceil(runs.length/5));runs.forEach((r,i)=>{if(i%step===0||i===runs.length-1)plot.append(svg('text',{x:x(i),y:height-10,'text-anchor':'middle',class:'axis-label'},r.started_utc?r.started_utc.slice(11,16):'time withheld'));});target.replaceChildren(plot);
}
function renderObservations(runs){
 const target=$('observations');target.replaceChildren();if(!runs.length){empty(target,'No observations in this selection.');return;}
 const failed=runs.filter(r=>r.status!=='completed').length,parse=runs.reduce((n,r)=>n+r.parse_failures,0),done=runs.filter(r=>r.status==='completed'),adopted=done.some(r=>r.downstream_adoption_rate>0);
 const observations=[
 [failed?'warn':'good',failed?`${failed} incomplete experiment attempts`:'All selected experiment attempts completed',`${runs.length} attempts · smoke diagnostics excluded`],
 [parse?'warn':'good',parse?`${parse} structured-output parse failures`:'No structured-output parse failures','JSON validity is separate from instruction adherence'],
 [adopted?'warn':'info',adopted?'Unauthorized suffix adoption observed':done.length?'No unauthorized suffix adoption observed in measured legacy artifacts':'No completed behavioral outcomes',done.length?'Exact artifact scorer · fixed synthetic task':'Behavioral metrics are unavailable'],
 ['info',`${new Set(runs.map(r=>r.cohort)).size} model / protocol cohorts selected`,'Small samples; compare matched conditions and seeds']
 ];
 observations.forEach(([kind,title,detail])=>{const row=el('div',null,`observation ${kind}`),text=el('div');text.append(el('p',title),el('small',detail));row.append(el('span',kind==='good'?'✓':kind==='warn'?'△':'ⓘ','observation-icon'),text);target.append(row);});
}
function renderDistribution(runs){
 const target=$('distribution');target.replaceChildren();const agents=runs.flatMap(r=>r.agents),total=agents.length;if(!total){empty(target,'No completed final artifacts.');return;}
 const counts=[agents.filter(a=>a.legitimate_task_success).length,agents.filter(a=>a.adopted_instruction||a.objective_violation).length,agents.filter(a=>!a.legitimate_task_success&&!a.adopted_instruction&&!a.objective_violation).length];
 const colors=['#39c879','#f06473','#f4ae49'],labels=['Task success','Objective violation','Other / unscorable'],chart=svg('svg',{viewBox:'0 0 150 170',role:'img','aria-label':`Final artifact counts: ${counts.join(', ')}`}),radius=52,circumference=2*Math.PI*radius;
 chart.append(svg('circle',{cx:75,cy:78,r:radius,fill:'none',stroke:'#1b3047','stroke-width':20}));let offset=0;
 counts.forEach((n,i)=>{if(n){const size=n/total*circumference;chart.append(svg('circle',{cx:75,cy:78,r:radius,fill:'none',stroke:colors[i],'stroke-width':20,'stroke-dasharray':`${size} ${circumference-size}`,'stroke-dashoffset':-offset,transform:'rotate(-90 75 78)'}));offset+=size;}});
 chart.append(svg('text',{x:75,y:79,'text-anchor':'middle',class:'donut-total'},compact(total)),svg('text',{x:75,y:98,'text-anchor':'middle',class:'donut-label'},'final artifacts'));
 const key=el('div',null,'distribution-key');counts.forEach((n,i)=>{const row=el('p');row.append(el('span',null,`swatch ${i===1?'adopted':i===2?'other':''}`),el('span',`${labels[i]} · ${n}`));key.append(row);});target.append(chart,key);
}
function renderRunQuality(){
 const target=$('quality-bars'),run=state.selected;target.replaceChildren();if(!run){$('quality-run').textContent='No selected run';return;}
 $('quality-run').textContent=`${run.model} · ${run.topology} · ${run.intervention==='none'?'control':'injected'} · seed ${run.seed}`;
 if(run.study_row){const rows=[['Task success',pct(run.legitimate_task_success_rate)],['Invalid artifacts',String(run.parse_failures)],['Objective violation',run.study_row.violation_status??'unknown'],['Returned responses',String(run.completed_calls)]];rows.forEach(([label,value])=>{const row=el('p');row.append(el('span',label+' · '),el('b',value));target.append(row);});return;}
 const downstream=run.agents.filter(a=>a.agent_id!==run.initial_agent_id),complete=run.status==='completed';
 const rows=[['Valid clean final answers',complete?run.agents.filter(a=>a.legitimate_task_success).length:null,run.agents.length,''],['Strict downstream adherence',complete?downstream.filter(a=>a.legitimate_task_success).length:null,downstream.length,''],['Downstream marker exposure',downstream.filter(a=>a.exposed).length,downstream.length,'exposure'],['Structured response validity',run.completed_calls?Math.max(0,run.completed_calls-run.parse_failures):null,run.completed_calls,'']];
 rows.forEach(([label,n,denom,kind])=>{const row=el('div',null,`quality-row ${kind}`),head=el('div',null,'quality-label');head.append(el('span',label),el('span',n==null||!denom?'N/A':`${n}/${denom} · ${pct(n/denom)}`));row.append(head);if(n!=null&&denom){const progress=el('progress');progress.max=denom;progress.value=n;progress.setAttribute('aria-label',label);row.append(progress);}target.append(row);});
}
