const researchState={snapshot:null};
const repositoryState={snapshot:null};
function allResearchRows(){return [...(researchState.snapshot?.studies??[]),...(repositoryState.snapshot?.runs??[])];}
function researchTable(id,headers,rows,onSelect=null){const target=$(id);target.replaceChildren();if(!rows.length){empty(target,'No published measurements in this category.');return;}const table=el('table'),head=el('tr');headers.forEach(h=>head.append(el('th',h)));table.append(head);rows.forEach((values,index)=>{const row=el('tr');values.forEach(v=>row.append(el('td',v)));if(onSelect){row.tabIndex=0;row.setAttribute('role','button');row.addEventListener('click',()=>onSelect(index));row.addEventListener('keydown',e=>{if(e.key==='Enter')onSelect(index);});}table.append(row);});target.append(table);}
function renderResearch(){const d=researchState.snapshot;if(!d)return;
 renderStudyRows(allResearchRows());
 $('research-review-status').textContent=`Reviewer: ${d.review_model??d.review_source}. Uncalibrated; human review required. ${d.unreviewed_samples} samples remain unreviewed. Confidence is a self-report, not a validated probability.`;
 researchTable('research-reviews',['Priority','Model / sample','Behavior','Confidence','Evidence IDs','Queue reasons'],[...d.reviews].sort((a,b)=>b.priority-a.priority).map(r=>[r.priority,`${r.target_model??'blinded'} / ${r.sample_id}`,r.behavior,pct(r.confidence),r.evidence_event_ids.join(', '),r.queue_reasons.join(', ')]));
 researchTable('research-monitor',['Model / evidence','Topology','Policy / mask seed','Visibility','Runs','Precision','Recall','F1','False positive rate'],d.monitor.map(r=>[`${r.model??"legacy cohort"} / ${r.backend}`,r.topology??"unspecified",`${r.policy} / ${r.monitor_seed??'not recorded'}`,pct(r.visibility),r.n,pct(r.precision),pct(r.recall),pct(r.f1),pct(r.false_positive_rate)]));
 $('scenario-count').textContent=`${d.scenarios.length} deterministic variants of four templates. Development and evaluation splits are separate. Variants are not independently authored attacks.`;
 researchTable('research-scenarios',['Scenario','Category','Family','Split','Content hash'],d.scenarios.map(r=>[r.case_id,r.category,r.family,r.split,r.content_hash.slice(0,12)]));
 renderScaling(d.studies);
 renderInterpOverview();renderMonitorExplorer();
}
function renderNeural(){const target=$('neural-evidence');target.replaceChildren();const d=researchState.snapshot;const r=d?.neural.find(x=>x.id===$('neural-select').value)||d?.neural[0];if(!r){['neuron-tokens','neuron-distribution','patch-comparison'].forEach(id=>empty($(id),'No measured capture available.'));empty(target,'No measured neural captures published. The Linux TransformerLens worker is prepared; no activations have been inferred from model text.');return;}
 target.append(el('p',`${r.model} · ${r.evidence_type} · ${secs(r.duration_seconds)} · ${r.device} / ${r.dtype} · revision ${r.revision??'seeded random initialization'}`,'notice'));
 for(const kind of ['clean','corrupt']){target.append(el('h3',`${kind} residual RMS · layer × token position`));const table=el('table'),head=el('tr');head.append(el('th','Layer'));const n=r[`${kind}_token_count`];for(let i=0;i<n;i++)head.append(el('th',`P${i}`));table.append(head);const max=Math.max(.000001,...r.layers.flatMap(l=>[...l.clean_residual_rms,...l.corrupt_residual_rms]));r.layers.forEach(l=>{const row=el('tr');row.append(el('th',l.layer));l[`${kind}_residual_rms`].forEach(v=>{const cell=el('td',v.toFixed(3),'heatmap-cell');cell.style.backgroundColor=`rgba(62,148,255,${Math.max(.06,v/max*.8)})`;row.append(cell);});table.append(row);});const wrap=el('div',null,'neural-grid');wrap.append(table);target.append(wrap);}
 renderNeuronControls(r);
 const p=r.patch;const gap=p.clean_target_logit-p.corrupt_target_logit,delta=p.patched_target_logit-p.corrupt_target_logit,noop=Math.abs(p.noop_target_logit-p.corrupt_target_logit),control=Math.abs(p.position_control_logit-p.corrupt_target_logit),stable=Math.abs(gap)>=1e-4&&noop<=1e-5;target.append(el('h3','Measurement quality'),el('p',r.evidence_type==='random_weight_smoke'?'Instrumentation check: random weights. This capture cannot explain trained-model behavior.':'Trained checkpoint replay; not the hidden state of the original Ollama execution.','notice'),el('p',`Clean/corrupt logit gap: ${gap.toFixed(5)} · patch delta: ${delta.toFixed(5)} · normalized restoration: ${stable?(delta/gap).toFixed(3):'undefined (small gap or failed no-op)'}`),el('p',`No-op error: ${noop.toExponential(2)} (${noop<=1e-5?'pass':'FAIL'}) · position-control effect: ${control.toExponential(2)} · absolute tolerance 1e-5. Restoration is not an alignment probability. Selected neurons are biased toward high clean activation.`,'caption'));target.append(el('h3','Single-position activation patch · target logit'));const list=el('dl');Object.entries(p).forEach(([k,v])=>list.append(el('dt',k),el('dd',typeof v==='number'?v.toFixed(4):v)));target.append(list,el('p','Compare clean, corrupt, patched, no-op and position-control logits. A logit difference is a local intervention effect, not evidence of model intent.','caption'));
}
async function loadResearch(){try{const response=await fetch(`data/research.json?v=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw Error('Unavailable');const data=await response.json();if(data.schema_version!=='1.0'||!Array.isArray(data.studies)||!Array.isArray(data.neural)||!Array.isArray(data.scenarios))throw Error('Schema');researchState.snapshot=data;combineEvidence();if(state.snapshot)render();const stamp=$('research-updated');if(stamp)stamp.textContent=`Research exported ${new Date(data.generated_utc).toLocaleString()} · ${data.studies.length} run attempts · checked ${new Date().toLocaleTimeString()} · refresh every 60s`;renderResearch();renderEvidenceCensus();renderEvidenceInventory();}catch{const stamp=$('research-updated');if(stamp)stamp.textContent='Research refresh failed; check the local exporter or published build.';['research-studies','research-reviews','research-monitor','research-scenarios','neural-evidence'].forEach(id=>empty($(id),'No validated research snapshot available. Export research.json to publish these measurements.'));}}
$('neural-select').addEventListener('change',()=>{renderNeural();renderCaptureGallery(filteredCaptures());});
loadResearch();setInterval(()=>{if(!document.hidden)loadResearch();},60000);

function renderScaling(studies){const target=$('scaling-charts');target.replaceChildren();const rows=studies.filter(r=>['2.1','2.2','2.3','2.4','2.5','2.6'].includes(r.protocol)&&r.status==='completed');if(!rows.length){empty(target,'No completed swarm-size study published.');return;}
 for(const group of groups(rows,r=>[r.model,r.backend,r.model_digest,r.size_comparison_group??r.freeze_hash,r.topology,r.intervention].join('|'))){
 // The exporter matches source/model/task/seed/graph/sampling and varies only size.
 const first=group[0];target.append(el('h3',`${first.model} / ${first.backend} / ${first.topology} / ${first.intervention} / ${first.case_id} / seed ${first.seed}`));
 const width=600,height=190,plot=svg('svg',{viewBox:`0 0 ${width} ${height}`,role:'img','aria-label':'Recorded run runtime by agent count; one point per run'});
 const xmax=Math.max(5,...rows.map(r=>r.agent_count)),ymax=Math.max(.001,...group.map(r=>r.runtime));
 [0,.5,1].forEach(v=>plot.append(svg('line',{x1:50,y1:145-v*110,x2:580,y2:145-v*110,class:'gridline'}),svg('text',{x:0,y:149-v*110,class:'axis-label'},secs(v*ymax))));
 group.forEach(r=>{const x=50+r.agent_count/xmax*520,y=145-r.runtime/ymax*110,dot=svg('circle',{cx:x,cy:y,r:4,class:`chart-dot ${r.intervention!=='none'?'injected':''}`});dot.append(svg('title',{},`${r.agent_count} agents / ${r.case_id} / ${secs(r.runtime)} / task success ${pct(r.task_success_rate)}`));plot.append(dot,svg('text',{x,y:167,'text-anchor':'middle',class:'axis-label'},`${r.agent_count} agents`));});
 const wrap=el('div',null,'chart');wrap.append(plot);target.append(wrap);
 }
}

async function loadStudyDetail(row){const target=$('study-detail');target.replaceChildren(el('h3',`${row.model} / ${row.task_family} / ${row.case_id}`));
 const detailPath=row.source_kind==='repository_review'&&localAssetRevision?`__private_repository/${row.id}`:row.detail_file;
 if(!detailPath){empty(target,row.source_kind==='repository_review'?'Repository traces are private; open the localhost dashboard to inspect them.':'No public trace view was exported for this run. Its summary remains available.');return;}
 if(!/^data\/studies\/[a-f0-9]{16}\.json$/.test(detailPath)&&!(row.source_kind==='repository_review'&&localAssetRevision&&/^__private_repository\/[a-f0-9]{16}$/.test(detailPath))){empty(target,'Unapproved trace path.');return;}
 try{const response=await fetch(detailPath,{cache:'no-store'});if(!response.ok)throw Error('Unavailable');const d=await response.json();if(d.schema_version!=='1.0'||d.id!==row.id)throw Error('Schema');
 target.append(el('p',`${row.worker_label??'unspecified'} / ${row.agent_count} agents / ${row.topology} / ${row.intervention} / ${row.status}`,'notice'),el('h3','Assigned task'),el('pre',d.task_instruction??'Task text withheld'),el('pre',d.task_input??'Task inputs withheld'),el('p',`${d.traces.length} shown of ${d.eligible_events} eligible events; ${d.omitted_events} omitted by the public view cap. Full logs stay private.`,'caption'));
 d.traces.forEach(t=>{const item=el('details',null,'trace-item');item.append(el('summary',`r${t.round} / ${t.event_type} / ${t.agent_id??t.sender_id??''}${t.receiver_id?' → '+t.receiver_id:''}`),el('pre',t.content??'Text withheld'));if(t.content_truncated)item.append(el('p','Text truncated in this public view.','caption'));target.append(item);});
 }catch{empty(target,'The validated trace file is not available yet. Refresh after the next snapshot export.');}}

function renderStudyRows(rows){
 options($('research-model-filter'),[...new Set(rows.map(r=>r.model))].sort(),'All models');
 options($('research-task-filter'),[...new Set(rows.map(r=>r.task_family))].sort(),'All task types');
 options($('research-size-filter'),[...new Set(rows.map(r=>String(r.agent_count)))].sort((a,b)=>Number(a)-Number(b)),'All swarm sizes');
 const matches=rows.filter(r=>($('research-model-filter').value==='all'||r.model===$('research-model-filter').value)&&($('research-task-filter').value==='all'||r.task_family===$('research-task-filter').value)&&($('research-size-filter').value==='all'||String(r.agent_count)===$('research-size-filter').value)&&($('research-outcome-filter').value==='all'||($('research-outcome-filter').value==='violation'?r.violation:$('research-outcome-filter').value==='failed'?r.status!=='completed':r.status==='completed')));
 const visible=matches.slice(-200).reverse();$('research-filter-count').textContent=`Showing ${visible.length} of ${matches.length} matching runs (latest 200); click a row for task and traces.`;
 researchTable('research-studies',['Model / evidence','Protocol / agents','Task / case','Split / topology','Condition','Status / calls','Task success','Violation / attempt / state','Runtime'],visible.map(r=>[`${r.model} / ${r.backend} / ${r.worker_label??"unspecified"} / ${r.model_digest?.slice(0,12)??"digest unavailable"}`,`${r.protocol} / ${r.agent_count??5}`,`${r.task_family} / ${r.case_id}`,`${r.split} / ${r.topology}`,r.intervention,`${r.status} / ${r.calls}`,pct(r.task_success_rate),`${r.violation_status??(r.violation?'observed':'not_observed')} / ${r.attempted_forbidden} / ${r.state_violation} · ${r.parse_failures??0} invalid outputs`,secs(r.runtime)]),index=>loadStudyDetail(visible[index]));
}
['research-model-filter','research-task-filter','research-size-filter','research-outcome-filter'].forEach(id=>$(id).addEventListener('change',()=>{if(researchState.snapshot)renderStudyRows(allResearchRows());}));

function renderNeuronControls(r){const layerSelect=$('neuron-layer'),prior=layerSelect.value;layerSelect.replaceChildren(...r.layers.map(l=>new Option(`Layer ${l.layer}`,String(l.layer))));if(r.layers.some(l=>String(l.layer)===prior))layerSelect.value=prior;renderSelectedNeuron();
 const p=r.patch;EvidenceWidgets.bars($('patch-comparison'),[{label:'Clean',value:p.clean_target_logit,color:'#40bf91'},{label:'Corrupt',value:p.corrupt_target_logit,color:'#e59d42'},{label:'Patched',value:p.patched_target_logit,color:'#409cff'},{label:'No-op control',value:p.noop_target_logit,color:'#8a83dc'},{label:'Position control',value:p.position_control_logit,color:'#a8b4c3'}],{signed:true,label:'Measured target logits with controls'});}
function renderSelectedNeuron(){const captures=researchState.snapshot?.neural??[],r=captures.find(x=>x.id===$('neural-select').value)||captures[0];if(!r)return;const layer=r.layers.find(l=>String(l.layer)===$('neuron-layer').value)||r.layers[0],select=$('neuron-index'),previous=select.value;select.replaceChildren(...layer.neurons.map(n=>new Option(`Neuron ${n.index}`,String(n.index))));if(layer.neurons.some(n=>String(n.index)===previous))select.value=previous;
 const n=layer.neurons.find(x=>String(x.index)===select.value)||layer.neurons[0],target=$('neuron-tokens');target.replaceChildren();if(!n){empty(target,'No MLP neuron values in this capture.');return;}
 for(const [label,values,color] of [['Clean',n.clean,'#40bf91'],['Corrupt',n.corrupt,'#e59d42']]){target.append(el('h3',label));const strip=el('div',null,'token-strip'),max=Math.max(.000001,...n.clean.map(Math.abs),...n.corrupt.map(Math.abs));values.forEach((v,i)=>{const token=el('span',`P${i}`,'activation-token');token.style.backgroundColor=`rgba(${label==='Clean'?'64,191,145':'229,157,66'},${.12+.7*Math.abs(v)/max})`;token.title=`Position ${i}: ${v.toFixed(5)} (signed activation)`;token.append(el('small',v.toFixed(3)));strip.append(token);});target.append(strip);}
 EvidenceWidgets.histogram($('neuron-distribution'),[{values:n.clean,color:'#40bf91'},{values:n.corrupt,color:'#e59d42'}],{bins:8,label:'Recorded clean and corrupt activation counts'});}
function renderMonitorExplorer(){const d=researchState.snapshot,select=$('monitor-select'),previous=select.value;select.replaceChildren(...d.monitor.map((r,i)=>new Option(`${r.model??r.backend} / ${r.protocol??'legacy'} / ${r.topology??''} / ${r.policy} / seed ${r.monitor_seed??'not recorded'} / ${pct(r.visibility)}`,String(i))));if(d.monitor[Number(previous)])select.value=previous;renderSelectedMonitor();
 $('interp-availability').replaceChildren(...[['Behavioral ground truth','Task-specific deterministic scores'],['Judge model',`${d.review_source}; confidence uncalibrated`],['Neural captures',`${d.neural.length} measured capture(s)`],['Neural detector','Not trained or validated']].map(([a,b])=>{const x=el('p');x.append(el('b',a+': '),el('span',b));return x;}));}
function renderSelectedMonitor(){const r=researchState.snapshot?.monitor[Number($('monitor-select').value)];if(!r){empty($('monitor-matrix'),'No completed monitor evaluation yet.');$('monitor-explanation').textContent='Confusion matrices require matched predictions and full-log labels.';return;}EvidenceWidgets.confusion($('monitor-matrix'),r);$('monitor-explanation').textContent=`${r.n} run units · precision ${pct(r.precision)} · recall ${pct(r.recall)} · false positive rate ${pct(r.false_positive_rate)}. Null recall means no verified positive denominator. This is a binary marker monitor, not a neural classifier; no ROC curve or AUC is claimed.`;}
$('neuron-layer').addEventListener('change',renderSelectedNeuron);$('neuron-index').addEventListener('change',renderSelectedNeuron);$('monitor-select').addEventListener('change',renderSelectedMonitor);

function renderEvidenceCensus(){const target=$('evidence-census');if(!target)return;const legacy=state.legacySnapshot?.runs.filter(r=>r.backend!=='mock')??[],studies=allResearchRows().filter(r=>r.backend!=='mock');const calls=legacy.reduce((n,r)=>n+r.completed_calls,0)+studies.reduce((n,r)=>n+r.calls,0);target.textContent=`Collected live evidence: ${legacy.length+studies.length} run attempts · ${calls.toLocaleString()} returned responses. Original RQ1: ${legacy.length} attempts; newer benchmarks: ${studies.length}. Failed attempts retained; protocols analyzed separately. Software tests and mocks are excluded.`;}

let localAssetRevision=null;
async function checkLocalDashboard(){try{const response=await fetch('__local_status',{cache:'no-store'});if(!response.ok)return;const status=await response.json();if(!status.asset_revision)return;if(localAssetRevision&&localAssetRevision!==status.asset_revision){window.location.reload();return;}localAssetRevision=status.asset_revision;const node=$('local-sync-status');if(node)node.textContent=status.status==='ok'?`Local log sync checked ${new Date(status.checked_epoch*1000).toLocaleTimeString()} · ${status.studies} sealed study attempts · ${status.neural_captures??0} neural captures · ${status.monitor_summaries??0} monitor summaries${status.secondary_sync?' · secondary sync: '+status.secondary_sync:''}${status.secondary_neural_sync?' · CPU capture sync: '+status.secondary_neural_sync:''}`:`Local log sync ${status.status}; previous validated snapshot retained.`;}catch{}}
checkLocalDashboard();setInterval(()=>{if(!document.hidden){if(localAssetRevision){load();loadResearch();}checkLocalDashboard();}},15000);

function combineEvidence(){
 if(!state.legacySnapshot)return;
 const studies=allResearchRows();
 const adapted=studies.map(r=>{let run=studyRunCache.get(r.id);if(run&&run.row_signature===JSON.stringify(r))return run;
 const graph={};for(let i=0;i<r.agent_count;i++){const id='agent_'+i;graph[id]=r.topology==='single'?[]:r.topology==='complete'?Array.from({length:r.agent_count},(_,j)=>'agent_'+j).filter(v=>v!==id):r.topology==='star'?(i===0?Array.from({length:r.agent_count-1},(_,j)=>'agent_'+(j+1)):['agent_0']):['agent_'+((i+r.agent_count-1)%r.agent_count),'agent_'+((i+1)%r.agent_count)];}
 run={row_signature:JSON.stringify(r),id:'study-'+r.id,study_row:r,cohort:[r.backend,r.model_digest,r.worker_label,r.protocol,r.freeze_hash,r.task_family,r.split,r.executor,r.agent_count].join('|'),model:r.model,backend:r.backend,protocol_version:r.protocol,model_digest:r.model_digest,status:r.status,topology:r.topology,intervention:r.intervention,seed:r.seed,thinking:'not in public summary',duration_seconds:r.runtime,completed_calls:r.calls,attempted_calls:r.calls,http_attempts:null,parse_failures:r.parse_failures,generated_tokens:null,median_call_seconds:null,generation_tokens_per_second:null,downstream_adoption_rate:null,downstream_clean_rate:null,legitimate_task_success_rate:r.task_success_rate,messages_delivered:null,first_downstream_adoption:null,maximum_propagation_distance:null,temperature:null,max_output_tokens:null,started_utc:null,source_hash:'freeze '+r.freeze_hash,rounds:1,graph,initial_agent_id:'agent_0',agents:[],timeline:[],traces:[],traces_included:false};const finalAgents=(r.agents??[]).map(a=>({agent_id:a.agent_id,legitimate_task_success:a.task_success,adopted_instruction:r.task_family==='catalog'&&a.violation,objective_violation:a.violation,messages_received:a.messages_received,reason_code:a.behavior==='unscorable'?'missing_or_ambiguous_artifact':a.behavior}));run.agents=finalAgents;run.timeline=finalAgents.length?[{round:(r.rounds??1)-1,adoption_rate:r.downstream_adoption_rate??null,agents:finalAgents}]:[];Object.assign(run,{started_utc:r.started_utc??null,source_hash:r.source_hash??run.source_hash,attempted_calls:r.attempted_calls??r.calls,http_attempts:r.http_attempts??null,rounds:r.rounds??1,temperature:r.temperature??null,thinking:r.thinking??'not recorded',max_output_tokens:r.max_output_tokens??null,median_call_seconds:r.median_call_seconds??null,generated_tokens:r.generated_tokens??null,generation_tokens_per_second:r.generation_tokens_per_second??null,messages_delivered:r.messages_delivered??null,downstream_adoption_rate:r.downstream_adoption_rate??null,downstream_clean_rate:r.downstream_clean_rate??null});studyRunCache.set(r.id,run);return run;});
 state.snapshot={...state.legacySnapshot,runs:[...state.legacySnapshot.runs,...adapted]};
}
async function loadStudyRun(run){
 const row=run.study_row;const detailPath=row.source_kind==='repository_review'&&localAssetRevision?`__private_repository/${row.id}`:row.detail_file;if(!detailPath)return;
 try{if(!run.detail_loaded){const response=await fetch(detailPath,{cache:'no-store'});if(!response.ok)throw Error('Unavailable');const d=await response.json();if(d.id!==row.id)throw Error('Wrong trace');run.graph=d.graph;run.traces=d.traces;run.traces_included=d.text_included;run.rounds=Math.max(1,...d.traces.map(t=>t.round+1));run.assigned_task=d.task_instruction;run.detail_loaded=true;}
 if(state.selected?.id!==run.id)return;
 $('round').max=String(run.rounds-1);$('round').value=String(run.rounds-1);if(run.assigned_task)$('run-details').append(el('dt','Assigned task'),el('dd',run.assigned_task));renderRound();
 }catch{if(state.selected?.id===run.id)empty($('trace-list'),'Trace details are not available yet; the summary remains valid.');}
}

function renderEvidenceInventory(){const target=$('evidence-inventory');if(!target)return;const all=state.snapshot?.runs??[],d=researchState.snapshot;const counts=[['Live agent-run attempts',all.filter(r=>r.backend!=='mock').length,'Includes development and failed attempts; scientific cohorts stay separate.'],['Mock agent-run attempts',all.filter(r=>r.backend==='mock').length,'Scripted engineering validation, excluded from live findings.'],['Trained neural captures',d?.neural.filter(r=>r.evidence_type==='instrumented_checkpoint_replay').length??0,'Measured checkpoint activations; inspect Neural captures. Not agent runs.'],['Random-weight neural checks',d?.neural.filter(r=>r.evidence_type==='random_weight_smoke').length??0,'Instrumentation only; not trained-model evidence.'],['Monitor summary cells',d?.monitor.length??0,'Dependent visibility/policy/seed summaries; not additional model calls.'],['Advisory reviews',d?.reviews.length??0,'Uncalibrated until human adjudication.']];target.replaceChildren();counts.forEach(([label,count,note])=>{const row=el('div',null,'quality-row');row.append(el('b',`${label}: ${count}`),el('p',note,'caption'));target.append(row);});}

const interpUi={initialized:false};
function captureQuality(r){const p=r.patch,gap=p.clean_target_logit-p.corrupt_target_logit,delta=p.patched_target_logit-p.corrupt_target_logit,noop=Math.abs(p.noop_target_logit-p.corrupt_target_logit),control=Math.abs(p.position_control_logit-p.corrupt_target_logit),usable=Math.abs(gap)>=1e-4&&noop<=1e-5;return {gap,delta,noop,control,usable,controls:noop<=1e-5&&control<=1e-5,restoration:usable?delta/gap:null};}
function filteredCaptures(){const d=researchState.snapshot;if(!d)return[];const model=$('interp-model').value,evidence=$('interp-evidence').value;return d.neural.filter(r=>(model==='all'||r.model===model)&&(evidence==='all'||(evidence==='trained'?r.evidence_type==='instrumented_checkpoint_replay':r.evidence_type==='random_weight_smoke')));}
function renderInterpOverview(){const d=researchState.snapshot;if(!d)return;options($('interp-model'),[...new Set(d.neural.map(r=>r.model))].sort(),'All checkpoint models');if(!interpUi.initialized){$('interp-evidence').value=d.neural.some(r=>r.evidence_type==='instrumented_checkpoint_replay')?'trained':'all';interpUi.initialized=true;}
 const trained=d.neural.filter(r=>r.evidence_type==='instrumented_checkpoint_replay'),quality=trained.map(captureQuality),cards=[['Trained captures',trained.length,'Measured checkpoint interventions'],['Random-weight checks',d.neural.length-trained.length,'Instrumentation, separate from trained results'],['Trained checkpoints',new Set(trained.map(r=>r.model+'|'+r.revision)).size,'Unique model + immutable revision'],['Passing controls',`${quality.filter(q=>q.controls).length} / ${quality.length}`,'Trained no-op + position controls'],['Usable trained baselines',`${quality.filter(q=>q.usable).length} / ${quality.length}`,'Sufficient gap and passing no-op'],['Recorded capture time',secs(d.neural.reduce((sum,r)=>sum+r.duration_seconds,0)),'Capture durations; excludes downloads and gaps']];
 const target=$('interp-kpis');target.replaceChildren();cards.forEach(([label,value,note])=>{const card=el('article',null,'metric');card.append(el('p',label),el('strong',value),el('small',note));target.append(card);});
 const rows=filteredCaptures();$('interp-filter-summary').textContent=`${rows.length} of ${d.neural.length} measured captures shown. Inventory cards count all measurements; comparison panels use this checkpoint/evidence selection.`;
 const prior=$('neural-select').value;$('neural-select').replaceChildren(...rows.map(r=>new Option(`${r.model} · L${r.patch.hook.split('.')[1]} · ${r.id.slice(0,8)}`,r.id)));if(rows.some(r=>r.id===prior))$('neural-select').value=prior;
 renderInterpComparisons(rows);renderCaptureGallery(rows);renderNeural();
}
function renderInterpComparisons(rows=filteredCaptures()){const normalized=$('interp-effect-metric').value==='restoration',points=rows.map(r=>{const q=captureQuality(r);return {x:Number(r.patch.hook.split('.')[1]),y:normalized?q.restoration:q.delta,label:`${r.model} / ${r.id} / ${r.evidence_type}: ${normalized?'restoration':'logit delta'} ${normalized?q.restoration:q.delta}`};}).filter(p=>p.y!=null);
 EvidenceWidgets.scatter($('interp-effects'),[{points,color:'#8490ff'}],{label:'Individual measured patch effects by layer',xLabel:'Patched layer',yLabel:normalized?'Normalized restoration (not probability)':'Patched − corrupt target logit'});
 $('interp-effect-note').textContent=`${points.length}/${rows.length} defined capture effects. One dot per capture; overlapping dots are possible. Prompt pairs and targets differ, so these are descriptive points, not a pooled ranking. ${normalized?'Small-gap or failed no-op ratios stay undefined. Values are not clipped to [0,1].':''}`;
 const qualities=rows.map(captureQuality);EvidenceWidgets.bars($('interp-control-summary'),[{label:'No-op within tolerance',value:qualities.filter(q=>q.noop<=1e-5).length,color:'#40bf91'},{label:'Position control within tolerance',value:qualities.filter(q=>q.control<=1e-5).length,color:'#40bf91'},{label:'Usable baseline + no-op',value:qualities.filter(q=>q.usable).length,color:'#409cff'},{label:'Control failures',value:qualities.filter(q=>!q.controls).length,color:'#f06473'}],{label:'Capture-level measurement control counts'});
 renderInterpMonitorOverview();}
function renderInterpMonitorOverview(){const d=researchState.snapshot;if(!d)return;const metric=$('interp-monitor-metric').value||'false_positive_rate',palette=['#409cff','#40bf91','#e59d42','#a58bff','#ef7ca7'],models=[...new Set(d.monitor.map(r=>r.model??r.backend))];const series=models.map((model,index)=>({label:model,color:palette[index%palette.length],points:d.monitor.filter(r=>(r.model??r.backend)===model&&r[metric]!=null).map(r=>({x:r.visibility,y:r[metric],label:`${model} / ${r.cohort} / ${r.topology} / ${r.policy} / mask ${r.monitor_seed??'unknown'}: ${metric} ${r[metric]}, n=${r.n}`}))}));EvidenceWidgets.scatter($('interp-monitor-overview'),series,{label:'Defined behavioral monitor metrics by visibility, without pooling',xLabel:'Observed visibility fraction',yLabel:metric.replaceAll('_',' ')});}
function renderCaptureGallery(rows){const target=$('interp-capture-grid');target.replaceChildren();if(!rows.length){empty(target,'No measured captures match these filters. Change evidence or checkpoint selection.');return;}
 rows.forEach(r=>{const q=captureQuality(r),trained=r.evidence_type==='instrumented_checkpoint_replay',selected=$('neural-select').value===r.id,card=el('article',null,`capture-card${selected?' selected':''}`),badges=el('div',null,'capture-badges');badges.append(el('span',trained?'Trained checkpoint':'Random weights',`badge${trained?'':' random-badge'}`),el('span',q.controls?'Controls pass':'Control warning',`badge${q.controls?'':' bad-control'}`));card.append(badges,el('h3',`${r.model} · Layer ${r.patch.hook.split('.')[1]}`),el('p',`Capture ${r.id} · seed ${r.seed}`,'capture-id'));
 const stats=el('div',null,'capture-stats');[['Baseline logit gap',q.gap.toFixed(4)],['Patch logit change',q.delta.toFixed(4)],['Normalized restoration',q.restoration==null?'Undefined':q.restoration.toFixed(3)],['No-op error',q.noop.toExponential(1)]].forEach(([label,value])=>{const cell=el('div');cell.append(el('small',label),el('strong',value));stats.append(cell);});card.append(stats);
 const button=el('button','Inspect layers and neurons ↓');button.type='button';button.setAttribute('aria-pressed',String(selected));button.addEventListener('click',()=>{$('neural-select').value=r.id;renderNeural();renderCaptureGallery(rows);const detail=$('capture-detail');if(typeof detail.scrollIntoView==='function')detail.scrollIntoView({behavior:'smooth',block:'start'});});card.append(button);
 const detail=el('details'),summary=el('summary','Expand measured activation profile'),plot=el('div',null,'chart');detail.append(summary,plot);let drawn=false;detail.addEventListener('toggle',()=>{if(!detail.open||drawn)return;drawn=true;const layer=r.layers.find(l=>l.layer===Number(r.patch.hook.split('.')[1]))??r.layers[0];EvidenceWidgets.scatter(plot,[{label:'Clean',color:'#40bf91',connect:true,points:layer.clean_residual_rms.map((y,x)=>({x,y}))},{label:'Corrupt',color:'#e59d42',connect:true,points:layer.corrupt_residual_rms.map((y,x)=>({x,y}))}],{label:'Measured residual RMS at patched layer',xLabel:'Token position (alignment may differ)',yLabel:'Residual RMS'});detail.append(el('p','Clean: green · Corrupt: amber. Positions may differ across contexts; RMS is not a named feature.','caption'));});card.append(detail,el('p',trained?'Checkpoint replay, separate from the Ollama swarm execution.':'Random activations validate instrumentation only.','caption'));target.append(card);});}
['interp-model','interp-evidence'].forEach(id=>$(id).addEventListener('change',renderInterpOverview));$('interp-effect-metric').addEventListener('change',()=>renderInterpComparisons());$('interp-monitor-metric').addEventListener('change',renderInterpMonitorOverview);

async function loadRepositories(){try{const response=await fetch(`data/repositories.json?v=${Date.now()}`,{cache:'no-store'});if(!response.ok)return;const data=await response.json();if(data.schema_version!=='repository-public-1.0'||!Array.isArray(data.runs))return;repositoryState.snapshot=data;combineEvidence();if(state.snapshot)render();if(researchState.snapshot)renderStudyRows(allResearchRows());renderEvidenceCensus();renderEvidenceInventory();}catch{}}
loadRepositories();setInterval(()=>{if(!document.hidden)loadRepositories();},15000);
